head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil21103";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil21103.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_applDd", fn: function () { return String(String((dma_pageContext.get("today") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Submit();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_linkDisclsApplList_oncellclick
 * @description grd_linkDisclsApplList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_linkDisclsApplList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_linkDisclsApplList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_linkDisclsApplList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadForm(r["subcomNm"], r["subcomIsurCd"], r["asstTotamtOvr10pctYn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_linkDisclsApplList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_goStatList_onclick
 * @description btn_goStatList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goStatList_onclick = function(e){
    try {
        scwin.goStatList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil21103.btn_goStatList_onclick' }); }
};

/**
 * @method
 * @name btn_Remove_onclick
 * @description btn_Remove 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Remove_onclick = async function(e){
    try {
        await scwin.remove()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21103.btn_Remove_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Submit
 * @description Submit 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Submit = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Submit",
        method: "post",
        action: action ?? "/company/linkDisclsAppl.do",
        ref: "dma_SubmitReq",
        target: "dlt_linkDisclsApplList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {String} subcomNm subcomNm
 * @param {String} subcomIsurCd subcomIsurCd
 * @param {String} asstTotamtOvr10pctYn asstTotamtOvr10pctYn
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (subcomNm, subcomIsurCd, asstTotamtOvr10pctYn) {
    $c.util.getComponent('ipt_subcomNm').setValue(subcomNm);
    $c.util.getComponent('dma_SubmitReq').set('subcomIsurCd', subcomIsurCd);
    const obj = $c.util.getComponent('rd_asstTotamtOvr10pctYnSel');
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].value === asstTotamtOvr10pctYn) {
            obj[i].checked = true;
            break;
        }
    }
    $c.util.getComponent('dma_SubmitReq').set('asstTotamtOvr10pctYn', asstTotamtOvr10pctYn);
};

/**
 * @method
 * @name chk
 * @description chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk = async function () {
    if ($c.util.getComponent('ipt_applDd').getValue()>= $c.util.getComponent('cal_lnkDisclsApplApplDd').getValue()) {
        await $c.win.alert('연계공시 적용신청일은  신청일보다 이후 일자 이어야 합니다.');
        $c.util.getComponent("cal_lnkDisclsApplApplDd").focus();
        return false;
    }
    if (($c.util.getComponent('cal_lnkDisclsApplApplDd').getValue() == null ? '' : String($c.util.getComponent('cal_lnkDisclsApplApplDd').getValue())) === '' || $c.util.getComponent('cal_lnkDisclsApplApplDd').getValue().indexOf(" ") === "") {
        await $c.win.alert("연계공시 적용신청일을 입력해 주세요");
        $c.util.getComponent("cal_lnkDisclsApplApplDd").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_subcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_subcomNm').getValue())) === '' || $c.util.getComponent('ipt_subcomNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("상장자회사를 입력해 주세요");
        $c.util.getComponent("ipt_subcomNm").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name remove
 * @description remove 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.remove = async function () {
    if (!await scwin.chk()) {
        return;
    }
    await scwin.loadPop();
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (type) {
    if ("rmv" !== type) {
        await $c.win.alert("잘못된 요청입니다. 다시 시도해주십시요");
        return false;
    }
    $c.util.getComponent('dma_SubmitReq').set('method', 'removeLinkDisclsAppl');
    await scwin.tx_fn_Submit('linkDisclsAppl.do');
};

/**
 * @method
 * @name goStatList
 * @description go Stat List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goStatList = function () {
    const linkDisclsAppURL = '/jldfil21100/jldfil21100.xml';
    $c.win.setPageFrameSrc($c.win.getFrame(), linkDisclsAppURL);
};

/**
 * @method
 * @name loadPop
 * @description load Pop 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.loadPop = async function () {
    const linkDisclsAppURL = '/jldfil21104/jldfil21104.xml?type=rmv';
    await $c.win.openPopup(linkDisclsAppURL, { id: "LinkDisclsNotice", scrollbars: false, resizable: false, width: "510", height: "730", type: "pageFramePopup" }, { method: "searchLinkDisclsApplList" });
};
